{"action": "write", "path": "semver.py", "content": "from functools import cmp_to_key


def _parse(v):
    v = v.strip()
    # split off build metadata (ignored for ordering)
    if '+' in v:
        core, _build = v.split('+', 1)
    else:
        core = v
    # split off pre-release
    if '-' in core:
        main, pre = core.split('-', 1)
        pre_parts = pre.split('.')
    else:
        main, pre_parts = core, None
    nums = [int(x) for x in main.split('.')]
    return nums, pre_parts


def _is_num(s):
    return s.isdigit()


def _cmp_ident(a, b):
    an, bn = _is_num(a), _is_num(b)
    if an and bn:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if an and not bn:
        return -1
    if not an and bn:
        return 1
    return (a > b) - (a < b)


def _cmp(a, b):
    na, pa = _parse(a)
    nb, pb = _parse(b)
    # compare major.minor.patch
    for x, y in zip(na, nb):
        if x != y:
            return (x > y) - (x < y)
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1  # no pre-release is higher
    if pb is None:
        return -1
    for x, y in zip(pa, pb):
        c = _cmp_ident(x, y)
        if c != 0:
            return c
    return (len(pa) > len(pb)) - (len(pa) < len(pb))


def sort_versions(vs):
    return sorted(vs, key=cmp_to_key(_cmp))
